cases.setup:
Create FileInterface Subject;
Subject.Filename = '@FILES@/input α.sv';
Subject.Format = 'TVHF_ASCII';
Create Spacecraft Sat;
Sat.NAIFId = -101141;
Sat.NAIFIdReferenceFrame = -910141;
Sat.CoordinateSystem = EarthMJ2000Eq;
Sat.X = 7000;
Sat.Y = 0;
Sat.Z = 0;
Sat.VX = 0;
Sat.VY = 7.5;
Sat.VZ = 0;
Create Variable ReloadAlive;
ReloadAlive = 41;

cases.reload_probe:
Sat.X = 8000;
Set Sat Subject (Data = {'CartesianState'});
ReloadAlive = ReloadAlive + 1;
